 let state;try{state=JSON.parse(localStorage.getItem(key));}catch{}if(!state?.enemy||fromSelection&&content&&state.contentId!==content.id)state=defaults(content||master.contents[0],policy);if(!Array.isArray(state.additional))state.additional=(master.contents.find(c=>c.id===state.contentId)?.enemies||[]).slice(1).map(normalizeEnemy);if(fromSelection){state.settings.objective=content?.defaultObjective??(content?.category==='ギガモン'?'damage':content?.breakChallenge?.model==='four-shield'?'break':policy==='farm'?'farm':'turns');state.settings.turns=content?.defaultTurns??(policy==='one'?1:2);}if(fromSelection&&simpleOptions){state.settings.objective=simpleOptions.objective;state.settings.turns=simpleOptions.turns;state.settings.hp=simpleOptions.hp;for(const k of ['aoeDamageLow','aoeDamageHigh','aoeHitsPerTurn','luckyHeal','aoeCounts'])if(simpleOptions[k]!==undefined)state.settings[k]=simpleOptions[k];state.ignoreSpecial=true;if(simple&&!simpleOptions.useSavedConditions){state.settings.minProcProbability=null;state.settings.zoneScenario='none';state.settings.conditionalTension=0;state.settings.spellProcScenario='guaranteed';state.settings.allowAI=false;state.settings.independentProcs=false;}else state.settings.zoneScenario=state.settings.zoneScenario||'none';if(!simpleOptions.useSavedConditions||simpleOptions.applyBattleScenario){Object.assign(state.settings,ProcProbability35.preset(simpleOptions.battleScenario||'standard'));}}if(state.contentId==='agiro'&&!state.breakGoalRevision){state.settings.objective='break';state.settings.shieldMaxHP=2400000;state.breakGoalRevision=1;}const shieldModel=master.contents.find(c=>c.id===state.contentId)?.breakChallenge;if(shieldModel?.model==='four-shield'&&!state.settings.shieldRates){state.settings.shieldRates=shieldModel.rates;state.settings.shieldMaxHP=shieldModel.maxHP;state.settings.shieldProvisional=!!shieldModel.provisional;}state.settings.allowCheer??=true;state.settings.allowPaths??=true;if(fromSelection&&simpleOptions)state.recommendationMode=simpleOptions.battleScenario==='recommend'&&state.settings.objective==='damage';let recommendationTried=false,recommendationFallback=false;let worker=null,result=null,revision=0,lastCandidate=null,selectedCandidate=0,comparisonBaseline=null,trial={fixedLead:null,excludedWeapons:[]};
